UPDATE tax_free_territories SET status='verified_available',regional_note='The official visitor scheme rules are verified. Kiosk opening hours are not published on the government page, so confirm access before departure.',updated_at=1790467200000 WHERE id='tf-je';

INSERT OR IGNORE INTO tax_free_rule_versions (id,territory_id,version_number,lifecycle,availability,program_name,summary,eligibility_json,purchases_json,store_steps_json,documents_json,goods_json,deadlines_json,customs_json,electronic_validation_json,payout_json,disclaimer,effective_from,effective_to,content_verified_at,source_checked_at,published_at,published_by,supersedes_version_id,created_at,updated_at) VALUES ('tf-je-research-v2','tf-je',2,'published','available','GST visitor refund scheme','Eligible visitors can reclaim Jersey GST on qualifying goods bought from an approved retailer and exported on a scheduled commercial flight or ferry.','["Not resident in Jersey","Present in Jersey for no more than 60 days in the calendar year","At least 16 years old","Not a crew member on the departing flight"]','["More than £100 with one approved retailer on the same day","Goods must carry GST and come from an approved retailer","Services, consumed goods, tobacco, vapes and fuel are excluded"]','["Confirm that the retailer participates","Complete the approved online Global Blue tax-free form","Keep the original payment receipts"]','["Passport or approved identity document","Original payment receipts","Global Blue tax-free record"]','["Take the goods out of Jersey","Keep goods available for any requested export check","Do not consume eligible goods before departure"]','{"export":"Leave Jersey with the goods within one month of purchase"}','["Validate export at a Global Blue kiosk after security at Jersey Airport or in the Elizabeth ferry terminal"]','["Use the Global Blue kiosk with identity documents and original receipts"]','["Global Blue processes the refund under the approved scheme","Operator charges may reduce the amount paid"]','The official visitor scheme rules are verified. Kiosk opening hours are not published on the government page, so confirm access before departure.','2026-09-27',NULL,1790467200000,1790467200000,1790467200000,'world-research-review','tf-je-world-v1',1790467200000,1790467200000);

