INSERT OR IGNORE INTO tax_free_rule_versions (id,territory_id,version_number,lifecycle,availability,program_name,summary,eligibility_json,purchases_json,store_steps_json,documents_json,goods_json,deadlines_json,customs_json,electronic_validation_json,payout_json,disclaimer,effective_from,effective_to,content_verified_at,source_checked_at,published_at,published_by,supersedes_version_id,created_at,updated_at) VALUES ('tf-pe-research-v2','tf-pe',2,'published','available','Tourist IGV refund — Tax Free Peru','Foreign non-domiciled tourists staying 2 to 60 days can request an IGV refund for qualifying goods bought in person from authorized establishments.','["Foreign individual not domiciled in Peru","Entered Peru as a tourist","Stay is at least 2 and no more than 60 calendar days per entry"]','["Goods bought in person from an authorized establishment","At least PEN 100 per qualifying purchase","Services do not qualify","Payment must use an internationally valid card in the tourist''s name"]','["State that you intend to claim before the invoice is issued","Obtain a Tax Free invoice and certificate","Keep the goods with you for export"]','["Travel identity document","Tax Free invoice","Tax Free certificate","Eligible debit or credit card in the tourist''s name"]','["The tourist who bought the goods must personally take them out of Peru"]','{"application":"Submit the request before the authorized stay in Peru ends","payment":"The collaborating entity states payment within five calendar days after a valid request"}','["Complete the departure validation assigned by the self-service kiosk or mobile application","Present goods when the system assigns the inspection channel"]','["Use the self-service module in the pre-boarding control area on the third floor of the new Jorge Chávez terminal or the supported mobile application"]','["Refund is credited to the registered debit or credit card","The collaborating entity may deduct a disclosed service fee"]','SUNAT publishes the operational process and Lima airport location. Confirm the authorized-store list and current operator terms before purchase.','2026-09-27',NULL,1790467200000,1790467200000,1790467200000,'world-research-review','tf-pe-world-v1',1790467200000,1790467200000);

